/*************************************************
* Name:        ntt
*
* Description: Inplace number-theoretic transform (NTT) in Rq.
*              input is in standard order, output is in bitreversed order
*
* Arguments:   - int64_t r[4096]: pointer to input/output vector of elements of Zq
**************************************************/
void ntt(int64_t r[PQMX_N]) {
  /* Harvey-style lazy butterflies with Shoup multiplication, as in NFLlib.
   * Coefficients are handled as unsigned values in [0, 4q), which fits in
   * 64 bits since q < 2^62. For a twiddle w in [0, q) with Shoup constant
   * w' = floor(w * 2^64 / q), w*y - hi(w'*y)*q lies in [0, 2q) for any 64-bit y,
   * so each butterfly needs one conditional subtraction and no Montgomery or
   * Barrett reduction. The output is congruent mod q to the previous
   * Montgomery-based version and is returned in [0, q). */
  uint64_t *x = (uint64_t *)r;
  const uint64_t q = PQMX_Q, q2 = 2 * (uint64_t)PQMX_Q;
  unsigned int len, start, j, k;
  uint64_t a, b, t, w, wp;

  /* Bring arbitrary int64 inputs into [0, 4q): a - (a >> 62)*q lies in
   * [-2c, 2^62 + c) for q = 2^62 - c, and adding q makes it nonnegative. */
  for(j = 0; j < PQMX_N; j++)
    x[j] = (uint64_t)(r[j] - (r[j] >> 62) * PQMX_Q + PQMX_Q);

  k = 1;
#ifdef __AVX2__
  /* Same butterfly on 4 lanes. AVX2 only has 32x32->64 multiplication
   * (vpmuludq), so 64-bit products are assembled from 32-bit halves:
   * hi(w'*b) exactly from 4 partial products, and the low halves of w*b and
   * qhat*q from 3 each. The halves of w, w' and q are split once per block.
   * There is no unsigned 64-bit compare, so a >= 2q is tested by flipping the
   * sign bit of both sides and using the signed compare. */
  const __m256i vq_lo = _mm256_set1_epi64x(PQMX_Q);
  const __m256i vq_hi = _mm256_set1_epi64x((uint64_t)PQMX_Q >> 32);
  const __m256i vq2 = _mm256_set1_epi64x(q2);
  const __m256i vsign = _mm256_set1_epi64x((int64_t)(1ULL << 63));
  const __m256i vq2m1s = _mm256_set1_epi64x((int64_t)((q2 - 1) ^ (1ULL << 63)));
  const __m256i vmask32 = _mm256_set1_epi64x(0xFFFFFFFF);
  __m256i va, vb, vbh, vw, vwh, vwp, vwph, p00, p01, p10, p11, mid, qh, wb, qq, vt;
  for(len = 2048; len >= 4; len >>= 1) {
    for(start = 0; start < PQMX_N; start = j + len) {
      w = zetas_shoup[k];
      wp = zetas_shoup_pre[k++];
      vw = _mm256_set1_epi64x(w);
      vwh = _mm256_set1_epi64x(w >> 32);
      vwp = _mm256_set1_epi64x(wp);
      vwph = _mm256_set1_epi64x(wp >> 32);
      for(j = start; j < start + len; j += 4) {
        va = _mm256_loadu_si256((const __m256i *)&x[j]);
        vb = _mm256_loadu_si256((const __m256i *)&x[j + len]);
        va = _mm256_sub_epi64(va, _mm256_and_si256(vq2,
               _mm256_cmpgt_epi64(_mm256_xor_si256(va, vsign), vq2m1s)));
        vbh = _mm256_srli_epi64(vb, 32);
        /* qh = hi(w' * b) */
        p00 = _mm256_mul_epu32(vb, vwp);
        p01 = _mm256_mul_epu32(vb, vwph);
        p10 = _mm256_mul_epu32(vbh, vwp);
        p11 = _mm256_mul_epu32(vbh, vwph);
        mid = _mm256_add_epi64(_mm256_srli_epi64(p00, 32),
              _mm256_add_epi64(_mm256_and_si256(p01, vmask32), _mm256_and_si256(p10, vmask32)));
        qh = _mm256_add_epi64(_mm256_add_epi64(p11, _mm256_srli_epi64(mid, 32)),
             _mm256_add_epi64(_mm256_srli_epi64(p01, 32), _mm256_srli_epi64(p10, 32)));
        /* wb = lo(w * b), qq = lo(qh * q) */
        wb = _mm256_add_epi64(_mm256_mul_epu32(vb, vw), _mm256_slli_epi64(
             _mm256_add_epi64(_mm256_mul_epu32(vbh, vw), _mm256_mul_epu32(vb, vwh)), 32));
        qq = _mm256_add_epi64(_mm256_mul_epu32(qh, vq_lo), _mm256_slli_epi64(
             _mm256_add_epi64(_mm256_mul_epu32(_mm256_srli_epi64(qh, 32), vq_lo),
                              _mm256_mul_epu32(qh, vq_hi)), 32));
        vt = _mm256_sub_epi64(wb, qq);
        _mm256_storeu_si256((__m256i *)&x[j], _mm256_add_epi64(va, vt));
        _mm256_storeu_si256((__m256i *)&x[j + len],
                            _mm256_add_epi64(_mm256_sub_epi64(va, vt), vq2));
      }
    }
  }
  (void)a; (void)b; (void)t;
#else
  for(len = 2048; len >= 4; len >>= 1) {
    for(start = 0; start < PQMX_N; start = j + len) {
      w = zetas_shoup[k];
      wp = zetas_shoup_pre[k++];
      for(j = start; j < start + len; j++) {
        a = x[j];
        a -= (a >= q2) ? q2 : 0;
        b = x[j + len];
        t = w * b - (uint64_t)(((unsigned __int128)wp * b) >> 64) * q;
        x[j] = a + t;
        x[j + len] = a - t + q2;
      }
    }
  }
#endif

  for(j = 0; j < PQMX_N; j++) {
    a = x[j];
    a -= (a >= q2) ? q2 : 0;
    a -= (a >= q) ? q : 0;
    x[j] = a;
  }
}

/*************************************************
* Name:        invntt_tomont
*
* Description: Inplace inverse number-theoretic transform in Rq and
*              multiplication by Montgomery factor 2^16.
*              Input is in bitreversed order, output is in standard order
*
* Arguments:   - int16_t r[4096]: pointer to input/output vector of elements of Zq
**************************************************/
void invntt(int64_t r[PQMX_N]) {
  unsigned int start, len, j, k;
  int64_t t, zeta;
  const int64_t f =  4539628424397366945L; // mont^2/1024

  k = 1023;
  for(len = 4; len < PQMX_N; len <<= 1) {
    for(start = 0; start < PQMX_N; start = j + len) {
      zeta = zetas[k--];
      for(j = start; j < start + len; j++) {
        t = r[j];
        r[j] = barrett_reduce(t + r[j + len]);
        r[j + len] = barrett_reduce(r[j + len] - t);
        r[j + len] = fqmul(zeta, r[j + len]);
      }
    }
  }
  for(j = 0; j < PQMX_N; j++)
    r[j] = fqmul(r[j], f);

}

/*************************************************
* Name:        basemul
*
* Description: Multiplication of polynomials in Zq[X]/(X^4-zeta)
*              used for multiplication of elements in Rq in NTT domain
*
* Arguments:   - int14_t r[4]: pointer to the output polynomial
*              - const int64_t a[4]: pointer to the first factor
*              - const int64_t b[4]: pointer to the second factor
*              - int64_t zeta: integer defining the reduction polynomial
**************************************************/
void basemul(int64_t r[4], const int64_t a[4], const int64_t b[4], int64_t zeta)
{
  /* Inputs are reduced to |x| <= q/2 < 2^61, so each product is below 2^122 and
   * every sum below stays under 2^124, inside the Montgomery input range.
   * Outputs satisfy |r| < 1.5*2^61, tighter than the previous per-product
   * version, so callers that add several outputs before reducing cannot
   * overflow. The wrapped-around terms (multiplied by X^4 = zeta) are summed
   * and reduced once, then multiplied by zeta (stored in Montgomery form)
   * inside the final reduction: 7 Montgomery reductions instead of 28. */
  int64_t x[4], y[4], hi;

  x[0] = barrett_reduce(a[0]); x[1] = barrett_reduce(a[1]);
  x[2] = barrett_reduce(a[2]); x[3] = barrett_reduce(a[3]);
  y[0] = barrett_reduce(b[0]); y[1] = barrett_reduce(b[1]);
  y[2] = barrett_reduce(b[2]); y[3] = barrett_reduce(b[3]);

  hi = montgomery_reduce((__int128)x[1]*y[3] + (__int128)x[2]*y[2] + (__int128)x[3]*y[1]);
  r[0] = montgomery_reduce((__int128)x[0]*y[0] + (__int128)hi*zeta);

  hi = montgomery_reduce((__int128)x[2]*y[3] + (__int128)x[3]*y[2]);
  r[1] = montgomery_reduce((__int128)x[0]*y[1] + (__int128)x[1]*y[0] + (__int128)hi*zeta);

  hi = montgomery_reduce((__int128)x[3]*y[3]);
  r[2] = montgomery_reduce((__int128)x[0]*y[2] + (__int128)x[1]*y[1] + (__int128)x[2]*y[0] + (__int128)hi*zeta);

  r[3] = montgomery_reduce((__int128)x[0]*y[3] + (__int128)x[1]*y[2] + (__int128)x[2]*y[1] + (__int128)x[3]*y[0]);
}

/*************************************************
* Name:        scalar_field_mul
*
* Description: Scalar multiplication of a polynomial in Zq[X]/(X^4-zeta)
*
* Arguments:   - int14_t r[4]: pointer to the output polynomial
*              - const int64_t a: scalar factor
*              - const int64_t b[4]: pointer to the input polynomial factor
**************************************************/
void scalar_field_mul(int64_t r[4], const int64_t a, const int64_t b[4]){
    unsigned int i;
    for(i=0;i<4;i++){
        r[i] = fqmul(a, b[i]);
        r[i] = fqmul(r[i], MONT2);
    }
}

